SELECT COUNT(*)
FROM product_option
WHERE product_id = #{productId}
  AND option_name = #{optionName}

SELECT option_id
FROM product_option
WHERE product_id = #{productId}
  AND option_name = #{optionName}
    LIMIT 1

SELECT COUNT(*)
FROM product_option_value
WHERE option_id = #{optionId}
  AND option_value = #{optionValue}
